/**
 * Generates the PWA icon set into `public/icons/`.
 *
 * Written as a dependency-free software rasteriser rather than shelling out to ImageMagick:
 * the app's build has no image toolchain, contributors may not have one, and the icons are
 * regenerated by `npm run icons` whenever the artwork changes. Shapes are evaluated with a
 * 4x4 supersample so the cloud edges stay clean at 32 px and at 512 px from the same code.
 *
 *   node scripts/generateIcons.mjs
 */
import { deflateSync } from 'node:zlib';
import { mkdirSync, writeFileSync } from 'node:fs';
import path from 'node:path';

const OUT_DIR = path.resolve(import.meta.dirname, '..', 'public', 'icons');

// ---------------------------------------------------------------------------------------------
// Canvas
// ---------------------------------------------------------------------------------------------

/** Premultiplied-free straight RGBA accumulation buffer, `samples` subpixels per pixel. */
function render(size, draw) {
  const data = new Uint8Array(size * size * 4);
  const SS = 4; // 4x4 supersampling
  for (let py = 0; py < size; py++) {
    for (let px = 0; px < size; px++) {
      let r = 0;
      let g = 0;
      let b = 0;
      let a = 0;
      for (let sy = 0; sy < SS; sy++) {
        for (let sx = 0; sx < SS; sx++) {
          // Sample at subpixel centres, normalised to 0..1.
          const x = (px + (sx + 0.5) / SS) / size;
          const y = (py + (sy + 0.5) / SS) / size;
          const c = draw(x, y); // [r,g,b,a] each 0..1
          // Composite over whatever has accumulated so far in this subpixel? No: `draw` returns
          // the already-composited colour for the whole stack at this point, so we only average.
          r += c[0] * c[3];
          g += c[1] * c[3];
          b += c[2] * c[3];
          a += c[3];
        }
      }
      const n = SS * SS;
      const alpha = a / n;
      const idx = (py * size + px) * 4;
      if (alpha > 1e-6) {
        data[idx] = Math.round((r / a) * 255);
        data[idx + 1] = Math.round((g / a) * 255);
        data[idx + 2] = Math.round((b / a) * 255);
      }
      data[idx + 3] = Math.round(alpha * 255);
    }
  }
  return data;
}

// ---------------------------------------------------------------------------------------------
// Shapes (all in normalised 0..1 coordinates)
// ---------------------------------------------------------------------------------------------

const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
const mix = (a, b, t) => a + (b - a) * t;
const smooth = (e0, e1, x) => {
  const t = clamp01((x - e0) / (e1 - e0));
  return t * t * (3 - 2 * t);
};

function circleSd(x, y, cx, cy, r) {
  return Math.hypot(x - cx, y - cy) - r;
}

function roundRectSd(x, y, x0, y0, x1, y1, r) {
  const cx = (x0 + x1) / 2;
  const cy = (y0 + y1) / 2;
  const hw = (x1 - x0) / 2 - r;
  const hh = (y1 - y0) / 2 - r;
  const dx = Math.abs(x - cx) - hw;
  const dy = Math.abs(y - cy) - hh;
  const outside = Math.hypot(Math.max(dx, 0), Math.max(dy, 0));
  return outside + Math.min(Math.max(dx, dy), 0) - r;
}

function polygonSd(x, y, pts) {
  // Signed distance is overkill here; a crossing test is enough and is exact for even-odd.
  let inside = false;
  for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
    const [xi, yi] = pts[i];
    const [xj, yj] = pts[j];
    if (yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside ? -0.001 : 0.001;
}

/** Coverage in 0..1 from a signed distance, with roughly one pixel of edge softness. */
function cover(sd, px = 0.0022) {
  return clamp01(0.5 - sd / (2 * px));
}

// ---------------------------------------------------------------------------------------------
// Artwork
// ---------------------------------------------------------------------------------------------

const CLOUD = [
  // [cx, cy, r] — a cumulus silhouette: a tall centre with two shoulders and a wide base.
  [0.5, 0.475, 0.205],
  [0.335, 0.553, 0.142],
  [0.672, 0.532, 0.158],
  [0.437, 0.393, 0.112],
];
const BASE = { x0: 0.246, y0: 0.503, x1: 0.786, y1: 0.664, r: 0.07 };

// A lightning bolt. The silhouette has to be a *simple* polygon: the diagonal that carries the
// zigzag must run continuously from the upper edge to the lower point, otherwise the shape
// self-intersects and an even-odd fill breaks it into two disconnected halves.
const BOLT = [
  [0.575, 0.560], // top right
  [0.380, 0.745], // lower left — left edge of the upper band
  [0.487, 0.762], // notch back out
  [0.365, 0.935], // tip
  [0.560, 0.775], // up the right side of the lower band
  [0.452, 0.758], // lower notch
  [0.640, 0.585], // back out to the right edge
];

const BG_TOP = [0.043, 0.067, 0.125]; // slate-950
const BG_BOTTOM = [0.098, 0.153, 0.263];
const CLOUD_TOP = [0.976, 0.980, 0.984];
const CLOUD_BOTTOM = [0.72, 0.755, 0.80];
const SHADOW = [0.36, 0.42, 0.50];
const BOLT_CORE = [0.996, 0.898, 0.196]; // amber-300
const BOLT_EDGE = [0.961, 0.62, 0.043];

/**
 * @param {object} opts
 * @param {boolean} opts.maskable  Full-bleed background with the art inset to the safe zone.
 * @param {boolean} opts.round     Rounded-square silhouette (for the "any" purpose icons).
 */
function makeArt({ maskable = false, round = true } = {}) {
  // Maskable icons are cropped to a circle by the launcher, so the art must sit inside the
  // central 80% "safe zone" or the bolt gets clipped.
  const k = maskable ? 0.78 : 1.0;
  const sx = (v) => 0.5 + (v - 0.5) * k;
  const sy = (v) => 0.5 + (v - 0.5) * k;
  const scale = (v) => v * k;

  return (x, y) => {
    let r = 0;
    let g = 0;
    let b = 0;
    let a = 0;

    const put = (cr, cg, cb, ca) => {
      if (ca <= 0) return;
      const ia = 1 - ca;
      r = cr * ca + r * ia;
      g = cg * ca + g * ia;
      b = cb * ca + b * ia;
      a = ca + a * ia;
    };

    // --- Backdrop -------------------------------------------------------------------------
    const bgShape = maskable
      ? 1
      : round
        ? cover(roundRectSd(x, y, 0.0, 0.0, 1.0, 1.0, 0.225))
        : 1;
    if (bgShape > 0) {
      const t = clamp01(y);
      // A soft glow behind the cloud keeps the flat gradient from looking like a slab.
      const glow = 1 - smooth(0.0, 0.62, Math.hypot(x - 0.5, y - 0.50));
      const cr = mix(BG_TOP[0], BG_BOTTOM[0], t) + glow * 0.055;
      const cg = mix(BG_TOP[1], BG_BOTTOM[1], t) + glow * 0.075;
      const cb = mix(BG_TOP[2], BG_BOTTOM[2], t) + glow * 0.105;
      put(cr, cg, cb, bgShape);
    }

    // --- Cloud ----------------------------------------------------------------------------
    let cloud = 0;
    for (const [cx, cy, cr] of CLOUD) {
      cloud = Math.max(cloud, cover(circleSd(x, y, sx(cx), sy(cy), scale(cr))));
    }
    cloud = Math.max(
      cloud,
      cover(roundRectSd(x, y, sx(BASE.x0), sy(BASE.y0), sx(BASE.x1), sy(BASE.y1), scale(BASE.r)))
    );

    if (cloud > 0) {
      // Shade top-to-bottom inside the cloud, and darken the last few percent of the underside
      // so the silhouette reads as a cumulus base rather than a flat blob.
      const t = smooth(0.33, 0.70, y);
      let cr = mix(CLOUD_TOP[0], CLOUD_BOTTOM[0], t);
      let cg = mix(CLOUD_TOP[1], CLOUD_BOTTOM[1], t);
      let cb = mix(CLOUD_TOP[2], CLOUD_BOTTOM[2], t);
      const under = smooth(0.60, 0.68, y) * 0.5;
      cr = mix(cr, SHADOW[0], under);
      cg = mix(cg, SHADOW[1], under);
      cb = mix(cb, SHADOW[2], under);
      put(cr, cg, cb, cloud);
    }

    // --- Bolt, with a glow ------------------------------------------------------------------
    const boltPts = BOLT.map(([bx, by]) => [sx(bx), sy(by)]);
    const insideBolt = polygonSd(x, y, boltPts) < 0;

    // Glow: radial falloff from the bolt's centre of mass.
    const boltR = 1 - smooth(0.02, 0.24, Math.hypot((x - 0.487) * 0.92, y - 0.74));
    if (!insideless(boltR)) put(1.0, 0.78, 0.20, boltR * 0.22);

    if (insideBolt) {
      // Vertical amber gradient so the bolt has a lit tip.
      const t = clamp01((y - 0.58) / 0.34);
      put(
        mix(BOLT_EDGE[0], BOLT_CORE[0], 0.35 + 0.65 * t),
        mix(BOLT_EDGE[1], BOLT_CORE[1], 0.35 + 0.65 * t),
        mix(BOLT_EDGE[2], BOLT_CORE[2], 0.35 + 0.65 * t),
        1
      );
    }

    return [r, g, b, a];
  };
}

/** Tiny helper so the glow line above reads clearly. */
function insideless(v) {
  return v <= 1e-4;
}

// ---------------------------------------------------------------------------------------------
// PNG encoding
// ---------------------------------------------------------------------------------------------

const CRC_TABLE = (() => {
  const table = new Int32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    table[n] = c;
  }
  return table;
})();

function crc32(buf) {
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

function chunk(type, data) {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length, 0);
  const body = Buffer.concat([Buffer.from(type, 'latin1'), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body), 0);
  return Buffer.concat([len, body, crc]);
}

function encodePng(width, rgba, height = width) {
  // Filter type 0 (None) on every scanline: the artwork is smooth, and deflate handles it well
  // without per-row filter heuristics.
  const stride = width * 4;
  const raw = Buffer.alloc((stride + 1) * height);
  for (let y = 0; y < height; y++) {
    raw[y * (stride + 1)] = 0;
    Buffer.from(rgba.buffer, rgba.byteOffset + y * stride, stride).copy(raw, y * (stride + 1) + 1);
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 6; // colour type: RGBA
  ihdr[10] = 0; // deflate
  ihdr[11] = 0; // adaptive filtering
  ihdr[12] = 0; // no interlace
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', ihdr),
    chunk('IDAT', deflateSync(raw, { level: 9 })),
    chunk('IEND', Buffer.alloc(0)),
  ]);
}

// ---------------------------------------------------------------------------------------------
// Output
// ---------------------------------------------------------------------------------------------

mkdirSync(OUT_DIR, { recursive: true });

const targets = [
  { file: 'icon-192.png', size: 192, art: { round: true } },
  { file: 'icon-512.png', size: 512, art: { round: true } },
  { file: 'icon-maskable-512.png', size: 512, art: { maskable: true } },
  { file: 'apple-touch-icon.png', size: 180, art: { round: false } },
  { file: 'favicon-32.png', size: 32, art: { round: true } },
];

for (const t of targets) {
  const px = render(t.size, makeArt(t.art));
  const png = encodePng(t.size, px);
  writeFileSync(path.join(OUT_DIR, t.file), png);
  console.log(`${t.file.padEnd(24)} ${t.size}x${t.size}  ${(png.length / 1024).toFixed(1)} kB`);
}

// ---------------------------------------------------------------------------------------------
// Store screenshot (1280x720), referenced by the manifest.
//
// It is generated rather than captured because the app needs WebGL and there is no browser in
// this toolchain. It shows the icon artwork on the app's own background with a storm-cell
// silhouette, so an installed app has a real screenshot entry instead of a broken reference.
// ---------------------------------------------------------------------------------------------

const SHOT_W = 1280;
const SHOT_H = 720;

function makeScreenshot() {
  const data = new Uint8Array(SHOT_W * SHOT_H * 4);
  const bgTop = [0.031, 0.043, 0.078];
  const bgHorizon = [0.09, 0.118, 0.179];
  const ground = [0.075, 0.086, 0.066];
  const cloudLit = [0.42, 0.45, 0.51];
  const cloudShade = [0.145, 0.163, 0.208];

  // A supercell, authored the same way as the icon: overlapping discs forming an anvil that
  // spreads downshear, a congested tower below it, and a bright mammatus-lit underside.
  // Coordinates are normalised; the anvil is deliberately much wider than the tower.
  const CLOUDS = [
    // anvil deck
    [0.30, 0.235, 0.115], [0.40, 0.208, 0.100], [0.50, 0.196, 0.094],
    [0.60, 0.200, 0.090], [0.70, 0.212, 0.084], [0.79, 0.232, 0.070],
    [0.86, 0.252, 0.055], [0.35, 0.262, 0.088], [0.46, 0.252, 0.078],
    [0.57, 0.250, 0.074], [0.67, 0.262, 0.066], [0.24, 0.262, 0.078],
    // tower
    [0.435, 0.320, 0.078], [0.445, 0.392, 0.070], [0.455, 0.462, 0.066],
    [0.462, 0.532, 0.064], [0.470, 0.600, 0.064], [0.478, 0.664, 0.066],
    [0.372, 0.352, 0.058], [0.520, 0.362, 0.056], [0.392, 0.440, 0.054],
    [0.535, 0.448, 0.052], [0.405, 0.520, 0.050], [0.548, 0.528, 0.048],
    // flanking congestus
    [0.300, 0.400, 0.046], [0.268, 0.462, 0.040], [0.616, 0.400, 0.042],
    [0.648, 0.460, 0.036],
    // low scud / shelf near the base
    [0.410, 0.716, 0.072], [0.500, 0.724, 0.074], [0.590, 0.720, 0.066],
    [0.330, 0.726, 0.056], [0.668, 0.730, 0.050],
  ];

  // Summed soft discs rather than a hard union: a `max` of hard-edged circles leaves the seams
  // between them visible wherever the shading differs, which made the anvil look like a heap of
  // overlapping balls. Accumulating a falloff and clamping gives a smooth, merged envelope.
  const coverage = (u, v) => {
    let c = 0;
    for (const [cx, cy, cr] of CLOUDS) {
      // Clouds are foreshortened vertically: the storm is 12 km tall and 30 km wide.
      const d = Math.hypot((u - cx) * 0.94, v - cy);
      if (d > cr * 1.5) continue;
      c += 0.62 * (1 - smooth(cr * 0.42, cr * 1.28, d));
    }
    return clamp01(c);
  };

  for (let y = 0; y < SHOT_H; y++) {
    const v = y / SHOT_H;
    for (let x = 0; x < SHOT_W; x++) {
      const u = x / SHOT_W;
      let r, g, b;
      if (v > 0.795) {
        const t = (v - 0.795) / 0.205;
        r = mix(ground[0], 0.028, t);
        g = mix(ground[1], 0.038, t);
        b = mix(ground[2], 0.032, t);
      } else {
        const t = Math.pow(v / 0.795, 1.7);
        r = mix(bgTop[0], bgHorizon[0], t);
        g = mix(bgTop[1], bgHorizon[1], t);
        b = mix(bgTop[2], bgHorizon[2], t);
      }

      // Distant horizon haze so the ground line is not a hard edge.
      const haze = smooth(0.70, 0.80, v) * (1 - smooth(0.795, 0.83, v));
      r = mix(r, 0.13, haze * 0.5);
      g = mix(g, 0.15, haze * 0.5);
      b = mix(b, 0.19, haze * 0.5);

      const c = coverage(u, v);
      if (c > 0) {
        // Lit from the upper left: brighter at the anvil top, dark and heavy at the base.
        const lit = 1 - smooth(0.18, 0.70, v);
        const edge = 1 - smooth(0.0, 1.0, Math.abs(u - 0.44) / 0.5);
        let cr = mix(cloudShade[0], cloudLit[0], lit * (0.55 + 0.45 * edge));
        let cg = mix(cloudShade[1], cloudLit[1], lit * (0.55 + 0.45 * edge));
        let cb = mix(cloudShade[2], cloudLit[2], lit * (0.55 + 0.45 * edge));
        // A little vertical banding gives the anvil some grain without drawing stripes across it.
        const grain = 0.06 * Math.sin(v * 220.0 + u * 24.0) * (1 - c);
        cr *= 1 - grain;
        cg *= 1 - grain;
        cb *= 1 - grain;
        r = mix(r, cr, c);
        g = mix(g, cg, c);
        b = mix(b, cb, c);
      }

      // Precipitation shaft under the tower, faintly lit by a distant flash.
      const shaft =
        Math.max(0, 1 - Math.abs(u - 0.478) / (0.055 + 0.10 * (v - 0.60))) *
        smooth(0.60, 0.70, v) *
        (1 - smooth(0.79, 0.82, v));
      if (shaft > 0) {
        r = mix(r, 0.115, shaft * 0.62);
        g = mix(g, 0.132, shaft * 0.62);
        b = mix(b, 0.175, shaft * 0.62);
      }

      // Intra-cloud lightning illuminating the tower from within. Kept and diffused inside the
      // cloud, where a flash actually shows, rather than on the ground beneath it.
      const flash =
        (1 - smooth(0.02, 0.22, Math.hypot((u - 0.492) * 1.25, (v - 0.505) * 0.85))) * clamp01(c * 1.4);
      if (flash > 0) {
        r = mix(r, 0.80, flash * 0.22);
        g = mix(g, 0.84, flash * 0.22);
        b = mix(b, 0.98, flash * 0.22);
      }

      const idx = (y * SHOT_W + x) * 4;
      data[idx] = Math.round(clamp01(r) * 255);
      data[idx + 1] = Math.round(clamp01(g) * 255);
      data[idx + 2] = Math.round(clamp01(b) * 255);
      data[idx + 3] = 255;
    }
  }

  // Composite the app icon into the lower-left, as a store card would present it.
  const icon = render(216, makeArt({ round: true }));
  const ox = 56;
  const oy = SHOT_H - 216 - 48;
  // A soft drop shadow behind the icon so it separates from the scene.
  for (let y = -18; y < 216 + 26; y++) {
    for (let x = -18; x < 216 + 26; x++) {
      const px = ox + x;
      const py = oy + y;
      if (px < 0 || px >= SHOT_W || py < 0 || py >= SHOT_H) continue;
      const d = Math.hypot(Math.max(0, Math.abs(x - 108) - 108), Math.max(0, Math.abs(y - 108) - 108));
      const shade = (1 - smooth(0, 34, d)) * 0.45;
      if (shade <= 0) continue;
      const di = (py * SHOT_W + px) * 4;
      data[di] = Math.round(data[di] * (1 - shade));
      data[di + 1] = Math.round(data[di + 1] * (1 - shade));
      data[di + 2] = Math.round(data[di + 2] * (1 - shade));
    }
  }
  for (let y = 0; y < 216; y++) {
    for (let x = 0; x < 216; x++) {
      const px = ox + x;
      const py = oy + y;
      if (px < 0 || px >= SHOT_W || py < 0 || py >= SHOT_H) continue;
      const si = (y * 216 + x) * 4;
      const a = icon[si + 3] / 255;
      if (a <= 0) continue;
      const di = (py * SHOT_W + px) * 4;
      data[di] = Math.round(icon[si] * a + data[di] * (1 - a));
      data[di + 1] = Math.round(icon[si + 1] * a + data[di + 1] * (1 - a));
      data[di + 2] = Math.round(icon[si + 2] * a + data[di + 2] * (1 - a));
      data[di + 3] = 255;
    }
  }
  return data;
}

const shotPng = encodePng(SHOT_W, makeScreenshot(), SHOT_H);
writeFileSync(path.join(OUT_DIR, 'screenshot-wide.png'), shotPng);
console.log(`screenshot-wide.png      1280x720  ${(shotPng.length / 1024).toFixed(1)} kB`);

// A scalable favicon for browsers that prefer SVG; same geometry, no supersampling needed.
const boltPath = BOLT.map(([x, y], i) => `${i === 0 ? 'M' : 'L'}${x.toFixed(3)} ${y.toFixed(3)}`).join(' ');
const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" role="img" aria-label="MeteoLab">
  <defs>
    <linearGradient id="bg" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#0b1120"/><stop offset="1" stop-color="#19273f"/>
    </linearGradient>
    <linearGradient id="cloud" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#f9fafb"/><stop offset="1" stop-color="#b8c1cc"/>
    </linearGradient>
    <linearGradient id="bolt" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#f59e0b"/><stop offset="1" stop-color="#fef08a"/>
    </linearGradient>
  </defs>
  <rect width="100" height="100" rx="22.5" fill="url(#bg)"/>
  <g fill="url(#cloud)">
    <circle cx="50" cy="47.5" r="20.5"/><circle cx="33.5" cy="55.3" r="14.2"/>
    <circle cx="67.2" cy="53.2" r="15.8"/><circle cx="43.7" cy="39.3" r="11.2"/>
    <rect x="24.6" y="50.3" width="54" height="16.1" rx="7"/>
  </g>
  <path d="${boltPath}Z" fill="url(#bolt)"/>
</svg>
`;
writeFileSync(path.join(OUT_DIR, '..', 'favicon.svg'), svg);
console.log('favicon.svg               vector');
